import{c as a,Q as e,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"神经网络与梯度下降","description":"","frontmatter":{},"headers":[],"relativePath":"01-deep-learning/nn-foundations.md","filePath":"01-deep-learning/nn-foundations.md"}'),n={name:"01-deep-learning/nn-foundations.md"};function i(l,t,s,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="神经网络与梯度下降" tabindex="-1">神经网络与梯度下降 <a class="header-anchor" href="#神经网络与梯度下降" aria-label="Permalink to &quot;神经网络与梯度下降&quot;">​</a></h1><blockquote><p>反向传播与优化器本质 —— 深度学习的第一性原理</p></blockquote><h2 id="神经元与前向传播" tabindex="-1">神经元与前向传播 <a class="header-anchor" href="#神经元与前向传播" aria-label="Permalink to &quot;神经元与前向传播&quot;">​</a></h2><p>神经网络的基本计算单元是<strong>人工神经元</strong>，其数学本质是一个仿射变换接非线性激活函数：</p><p>$$ y = \\sigma(Wx + b) $$</p><p>其中 $W$ 为权重矩阵，$x$ 为输入向量，$b$ 为偏置项，$\\sigma$ 为非线性激活函数。</p><p>多层神经元堆叠形成<strong>深度</strong>神经网络，前向传播（Forward Propagation）即输入信号从输入层逐层计算流向输出层的过程。</p><h2 id="损失函数" tabindex="-1">损失函数 <a class="header-anchor" href="#损失函数" aria-label="Permalink to &quot;损失函数&quot;">​</a></h2><p>损失函数（Loss Function）衡量模型预测值与真实标签之间的差异：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>常用损失函数</th></tr></thead><tbody><tr><td>回归</td><td>MSE（均方误差）</td></tr><tr><td>二分类</td><td>Binary Cross-Entropy</td></tr><tr><td>多分类</td><td>Categorical Cross-Entropy</td></tr></tbody></table><h2 id="反向传播" tabindex="-1">反向传播 <a class="header-anchor" href="#反向传播" aria-label="Permalink to &quot;反向传播&quot;">​</a></h2><p><strong>反向传播（Backpropagation）</strong> 是训练神经网络的核心算法，其数学基础是链式法则：</p><ol><li><strong>前向传播</strong>：计算每一层的输出</li><li><strong>计算损失</strong>：对比预测值与真实值</li><li><strong>反向传播</strong>：从输出层向输入层逐层计算损失对每个参数的梯度</li><li><strong>参数更新</strong>：使用优化器根据梯度更新参数</li></ol><h2 id="优化器演进" tabindex="-1">优化器演进 <a class="header-anchor" href="#优化器演进" aria-label="Permalink to &quot;优化器演进&quot;">​</a></h2><h3 id="sgd-随机梯度下降" tabindex="-1">SGD（随机梯度下降） <a class="header-anchor" href="#sgd-随机梯度下降" aria-label="Permalink to &quot;SGD（随机梯度下降）&quot;">​</a></h3><p>最基本的优化方法：</p><p>$$ \\theta_{t+1} = \\theta_t - \\eta \\nabla_\\theta J(\\theta_t) $$</p><h3 id="sgd-momentum" tabindex="-1">SGD + Momentum <a class="header-anchor" href="#sgd-momentum" aria-label="Permalink to &quot;SGD + Momentum&quot;">​</a></h3><p>引入动量项，加速收敛并减少震荡：</p><p>$$ v_t = \\beta v_{t-1} + (1 - \\beta)\\nabla_\\theta J(\\theta_t) $$ $$ \\theta_{t+1} = \\theta_t - \\eta v_t $$</p><h3 id="adam" tabindex="-1">Adam <a class="header-anchor" href="#adam" aria-label="Permalink to &quot;Adam&quot;">​</a></h3><p>结合 Momentum 与 RMSProp 的自适应学习率算法，目前最广泛使用的优化器：</p><ul><li><strong>一阶矩估计</strong>（动量）：跟踪梯度的指数移动平均</li><li><strong>二阶矩估计</strong>（自适应学习率）：跟踪梯度平方的指数移动平均</li><li><strong>偏差修正</strong>：在训练初期补偿初始化偏差</li></ul><h2 id="关键直觉" tabindex="-1">关键直觉 <a class="header-anchor" href="#关键直觉" aria-label="Permalink to &quot;关键直觉&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">核心洞察</p><p>反向传播本质上就是「链式法则的工程化实现」。理解这一点，就理解了为什么深度学习框架都需要自动微分系统。</p></div><p>训练神经网络的本质是：<strong>在一个高维非凸空间中，使用一阶梯度信息寻找能最小化损失的参数配置</strong>。所有优化技巧 —— 学习率调度、梯度裁剪、Batch Normalization —— 都是为了让这个搜索过程更稳定、更快速。</p>',26)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
